function solve(region, consent) {
    // Default telemetry policy:
    // - EU: disabled by default (consent required)
    // - US: enabled by default
    // - If consent is missing (null), we cannot determine if it's enabled.

    if (region === 'EU') {
        return false;
    } else if (region === 'US') {
        return true;
    } else {
        return null; // Unknown region
    }
}
